package trimmed

// AlgebraicShellBooleanHistory maps both original shells to the qualified
// Boolean. Each row has the same index as its original face or model edge.
// An empty row means that entity has no retained portion. SectionEdges are
// generated by the Boolean and do not appear in either original edge table.
type AlgebraicShellBooleanHistory struct {
	Faces, Edges [2][][]int
	SectionEdges []int
}

// History returns a new snapshot of exact topological ancestry. Original
// edge rows follow the original parameter direction, including when the
// physical face orientation is reversed by a cut.
func (s AlgebraicShellBoolean) History() AlgebraicShellBooleanHistory {
	var h AlgebraicShellBooleanHistory
	if s.source == nil {
		return h
	}
	var edgeRows [2][]int
	for i, operand := range [2]Solid{s.source.a, s.source.b} {
		h.Faces[i] = make([][]int, len(operand.faces))
		h.Edges[i] = make([][]int, len(operand.edges))
		edgeRows[i] = make([]int, len(s.parts[i].Subdivision.edges))
		for j := range edgeRows[i] {
			edgeRows[i][j] = -1
		}
	}
	for i, f := range s.faces {
		h.Faces[f.Operand][f.Original] = append(h.Faces[f.Operand][f.Original], i)
	}
	for i, e := range s.index {
		if e.SectionPiece >= 0 {
			h.SectionEdges = append(h.SectionEdges, i)
		} else if e.OriginalSubdivisionEdge >= 0 {
			edgeRows[e.Operand][e.OriginalSubdivisionEdge] = i
		}
	}
	for i, rows := range edgeRows {
		for piece, id := range rows {
			if id >= 0 {
				original := s.parts[i].Subdivision.edges[piece].Original
				h.Edges[i][original] = append(h.Edges[i][original], id)
			}
		}
	}
	return h
}
